find:
for edit in &mut parts.map_next {
    next = edit(next, page.value())?;
}
Ok(Some(next))

replace:
let mut failure = None;
for edit in &mut parts.map_next {
    match edit(next.clone(), page.value()) {
        Ok(edited) => next = edited,
        Err(error) => { failure.get_or_insert(error); }
    }
}
failure.map_or(Ok(Some(next)), Err)
